import{_ as p,r as a,o,c,e as n,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const x=JSON.parse('{"title":"Менеджер сайтов - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":3,"title":"Введение","slug":"введение","link":"#введение","children":[]},{"level":2,"title":"Проверка состояния конфигурации сайта","slug":"проверка-состояния-конфигурации-саита","link":"#проверка-состояния-конфигурации-саита","children":[]},{"level":2,"title":"Получение сайта","slug":"получение-саита","link":"#получение-саита","children":[]},{"level":2,"title":"Доступ к нескольким сайтам","slug":"доступ-к-нескольким-саитам","link":"#доступ-к-нескольким-саитам","children":[]},{"level":2,"title":"Контекст сайта","slug":"контекст-саита","link":"#контекст-саита","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}],"relativePath":"3.x/ru/extend/services/site.md","filePath":"3.x/ru/extend/services/site.md"}'),u={name:"3.x/ru/extend/services/site.md"};function r(k,s,d,g,h,m){const e=a("pre-heading"),t=a("post-heading");return o(),c("div",null,[n(e),s[0]||(s[0]=l("h1",null,"Менеджер сайтов",-1)),n(t),s[1]||(s[1]=i(`<h3 id="введение"><a href="#введение" class="header-anchor">#</a> Введение</h3><p>Глобальный фасад <code>Site</code> включён в October CMS для предоставления инструментов работы с <a href="./../../cms/resources/multisite.html">мультисайтовыми реализациями</a>. Все необязательные мультисайтовые функции включаются или отключаются с помощью конфигурационного файла <strong>config/multisite.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;features&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;cms_maintenance_setting&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span><span class="token punctuation">,</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">]</span>
</code></pre></div><p>Метод <code>hasFeature</code> используется для проверки, включена ли определённая мультисайтовая функция.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$useMultisite</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">hasFeature</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms_maintenance_setting&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="проверка-состояния-конфигурации-саита"><a href="#проверка-состояния-конфигурации-саита" class="header-anchor">#</a> Проверка состояния конфигурации сайта</h2><p>Используйте <code>hasAnySite</code> для проверки, доступен ли хотя бы один включённый сайт.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">hasAnySite</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Метод <code>hasMultiSite</code> вернёт true, если доступно несколько определений сайтов.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">hasMultiSite</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Метод <code>hasSiteGroups</code> вернёт true, если несколько определений сайтов используют группировку.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">hasSiteGroups</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="получение-саита"><a href="#получение-саита" class="header-anchor">#</a> Получение сайта</h2><p>Запрос сайта вернёт экземпляр <code>System\\Models\\SiteDefinition</code> с доступными атрибутами, загруженными из драйвера кэша или базы данных.</p><p>Метод <code>getPrimarySite</code> возвращает определение основного сайта, используемое в качестве запасного варианта для каждого случая.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$site</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">getPrimarySite</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Тема фронтенда имеет выбранный сайт, который используется при рендеринге CMS-страниц. Метод <code>getActiveSite</code> вернёт этот сайт.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$site</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">getActiveSite</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Аналогично, в панели администрирования можно выбрать сайт, и его можно получить с помощью метода <code>getEditSite</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$site</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">getEditSite</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для поиска сайта по его уникальному идентификатору используйте <code>getSiteFromId</code> с идентификатором.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$siteFour</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">getSiteFromId</span><span class="token punctuation">(</span><span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для поиска сайта по его коду локали используйте <code>getSiteForLocale</code>, передав желаемую локаль.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$frenchSite</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">getSiteForLocale</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="доступ-к-нескольким-саитам"><a href="#доступ-к-нескольким-саитам" class="header-anchor">#</a> Доступ к нескольким сайтам</h2><p>Если возвращается несколько сайтов, они будут представлены как заполненный экземпляр объекта <code>October\\Rain\\Database\\Collection</code>.</p><p>Вывести список всех сайтов, включая отключённые, можно с помощью метода <code>listSites</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$sites</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">listSites</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вывести только включённые сайты можно с помощью метода <code>listEnabled</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$sites</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">listEnabled</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вывести сайты, включённые в панели администрирования, можно с помощью <code>listEditEnabled</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$sites</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">listEditEnabled</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="контекст-саита"><a href="#контекст-саита" class="header-anchor">#</a> Контекст сайта</h2><p>Контекст сайта используется для определения активного сайта, и это автоматически ограничит запросы этим сайтом. В некоторых случаях используется глобальное состояние, позволяющее доступ к данным всех сайтов.</p><p>Используйте <code>withContext</code> для переключения контекста на другой сайт, передав идентификатор нужного сайта.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">withContext</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Models in site 2 are now available.</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Активация глобального контекста выполняется с помощью <code>withGlobalContext</code> и передачи замыкания.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">withGlobalContext</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// All models are available in here.</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Используйте метод <code>hasGlobalContext</code> для проверки, активировано ли в данный момент глобальное состояние.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$global</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">hasGlobalContext</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4><div class="custom-block also"><ul><li><a href="./../../cms/resources/multisite.html">Мультисайт</a></li><li><a href="./../database/traits.html">Трейт Multisite</a></li></ul></div>`,42))])}const S=p(u,[["render",r]]);export{x as __pageData,S as default};
